const b=(symbol,type)=>({symbol,type});
const D=(id,symbol,type,definition,depends_on=[],binders=[],objects=[])=>({id,symbol,type,definition,depends_on,requires:[],binders,objects});
const defs=[
D("D001","I","subset of ℝ","I=[0,1]={t∈ℝ : 0≤t and t≤1}.",[],[b("t","ℝ")],[]),
D("D002","ediam","extended diameter, for subsets of a pseudo extended metric space","For a pseudo extended metric space Z and B⊆Z, ediam(B)=sup{edist(x,y): x∈B, y∈B} in [0,∞], with sup ∅=0.",[],[b("Z","pseudo extended metric space"),b("B","subset of Z"),b("x","Z"),b("y","Z")],[]),
D("D003","diam","real diameter notation for subsets of a metric space","For a metric space Z and B⊆Z, diam(B)=(ediam(B)).toReal, where toReal agrees with finite nonnegative reals and sends ∞ to 0. Only finite-extended-diameter sets are assigned real diameters in our covering arguments. Empty sets and singletons have diameter zero.",["D002"],[b("Z","metric space"),b("B","subset of Z")],["ediam"]),
D("D004","C","extended nonnegative content C_p(r,B), also denoted YuiContent p r B","For a metric (or extended metric) space Z, real p, r∈[0,∞], B⊆Z, define C_p(r,B)=inf_{U:ℕ→Set Z} inf_{B⊆⋃i U_i} inf_{∀i ediam(U_i)≤r} ∑_{i≥0} sup_{h:U_i≠∅}(ediam(U_i))^p. Empty infima are ∞ and empty suprema are 0. Thus empty cover members cost zero, also at p=0. This is exactly YuiContent in basis-registry.json/lean_header. For a real scale δ≥0, C_p(δ,B) means C_p(ofReal δ,B); nonnegative real finite costs are embedded in [0,∞].",["D002"],[b("Z","extended metric space"),b("p","ℝ"),b("r","[0,∞]"),b("B","subset of Z"),b("U","ℕ→Set Z"),b("δ","nonnegative real")],["ediam"]),
D("D005","μH","unnormalized diameter-power Hausdorff measure μH[p] on Borel extended metric spaces","μH[p] is the native unnormalized Hausdorff measure, MeasureTheory.Measure.hausdorffMeasure p = Measure.mkMetric (r↦r^p). Its underlying outer measure is obtained from the metric outer measure construction: at each positive scale infimize the sums of diameter powers of countable covers, empty members costing zero, then take the supremum as the scale tends to zero. Evaluation μH[p](B) is the outer-measure value on any B⊆Z, with no measurability assumption on B. The exact native formula, including all extended scales, is registered in M001.",["D002","D004"],[b("Z","extended metric space with its Borel measurable structure"),b("p","ℝ"),b("B","subset of Z"),b("r","[0,∞]")],["ediam","C"]),
